<template>
    <div class="container layout">
        <div class="row gx-0">
            <div
                class="col-lg-2 col-md-12 col-sm-12 h-auto filter_area"
                id="filterArea"
            >
                <div
                    class="d-flex justify-content-center text-center flex-column content p-1 row gx-0"
                    style="border-radius: 10px"
                >
                    <span
                        @click="toggleFilterCollapse()"
                        class="fs-6"
                        data-bs-toggle="collapse"
                        :id="'collapseBtn_filter'"
                        :href="'#collapse_filter'"
                        role="button"
                        aria-expanded="true"
                        :aria-controls="'collapse_filter'"
                    >
                        中類篩選/搜尋<i
                            :id="'icon_filter'"
                            class="el-icon-caret-right"
                        ></i>
                    </span>
                    <div
                        class="collapse show w-100 col-12"
                        :id="'collapse_filter'"
                    >
                        <div class="row gx-0">
                            <div
                                class="p-1 d-flex justify-content-between col-12"
                            >
                                <el-input
                                    class="flex-grow-1"
                                    size="mini"
                                    placeholder="輸入關鍵字搜尋"
                                    v-model="searchInput"
                                />
                                <i
                                    class="bi bi-search fs-5 ps-2 searchBtn"
                                    @click="handleTypeFilter"
                                ></i>
                            </div>
                            <small
                                v-if="bookSoldTypeList.length == 0"
                                style="color: red"
                            >
                                請至少選擇一項販售類型</small
                            >
                            <div
                                class="ps-1 pe-1 col-lg-12 col-md-6 col-sm-4 col-4"
                            >
                                <div class="soldTypefilter">
                                    <el-checkbox-group
                                        v-model="bookSoldTypeList"
                                    >
                                        <el-checkbox label="entity"
                                            >實體書</el-checkbox
                                        >
                                        <el-checkbox label="ebook"
                                            >電子書</el-checkbox
                                        >
                                    </el-checkbox-group>
                                </div>
                            </div>
                            <div
                                class="ps-1 pe-1 col-lg-12 col-md-6 col-sm-4 col-4"
                                v-for="(item, index) in collapseBtnType"
                            >
                                <div
                                    class="collapse_btn_type p-1 d-flex"
                                    :class="{ selected: item.show }"
                                    :id="'collapseBtn_type_' + index"
                                    tabindex="0"
                                >
                                    <div
                                        @click="toggleBtnTypeCollapse(index)"
                                        class="d-flex justify-content-evenly w-100"
                                        data-bs-toggle="collapse"
                                        :href="
                                            '#collapse_type_' +
                                            index +
                                            '_subType'
                                        "
                                        style="cursor: pointer"
                                    >
                                        <input
                                            type="checkbox"
                                            role="button"
                                            class="menu"
                                            :id="'hamburgerBtn_' + index"
                                            :checked="item.show"
                                        />

                                        <div class="flex-grow-1">
                                            {{ item.name }}
                                        </div>
                                    </div>
                                </div>
                                <div
                                    class="collapse collapse_type_subType"
                                    :id="'collapse_type_' + index + '_subType'"
                                >
                                    <div
                                        v-for="(
                                            subType, index2
                                        ) in item.subTypes"
                                        class="form-check m-0 p-1 d-flex"
                                    >
                                        <div>
                                            <input
                                                type="checkbox"
                                                class="filter_checkbox"
                                                v-model="item.checked[index2]"
                                                :id="
                                                    'type_' +
                                                    index +
                                                    '_subTypeCheck_' +
                                                    index2
                                                "
                                            />
                                        </div>
                                        <label
                                            class="form-check-label flex-grow-1"
                                            :for="
                                                'Type_' +
                                                index +
                                                '_subTypeCheck_' +
                                                index2
                                            "
                                        >
                                            {{ subType }}
                                        </label>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="col-lg-10 col-md-12 col-sm-12">
                <div>
                    排序:
                    <el-dropdown trigger="click">
                        <span class="el-dropdown-link">
                            {{ sort
                            }}<i class="el-icon-arrow-down el-icon--right"></i>
                        </span>
                        <el-dropdown-menu slot="dropdown">
                            <el-dropdown-item
                                v-for="(item, index) in sortType"
                                :key="index"
                                @click.native="handleSortChange(item, index)"
                                >{{ item }}</el-dropdown-item
                            >
                        </el-dropdown-menu>
                    </el-dropdown>
                </div>
                <div v-if="dataloaded" class="booklist">
                    <div v-if="bookListInfo.length == 0" class="row gx-0">
                        <div class="d-flex justify-content-center">
                            暫無資料
                        </div>
                    </div>
                    <div v-else class="row gx-0">
                        <div
                            v-for="item in bookListInfo"
                            class="col-lg-12 col-md-6 col-sm-6 col-12 booklist_content"
                        >
                            <div class="row gx-0">
                                <div
                                    class="col-lg-2 col-md-6 col-sm-12 col-6 p-1 photo d-flex justify-content-center align-items-center"
                                >
                                    <div
                                        v-if="item.discount != 0"
                                        class="badge"
                                    >
                                        <span class="fs-6">{{
                                            item.discount
                                        }}</span>
                                        折
                                    </div>
                                    <img :src="item.contentPagePhoto[0]" />
                                    <!-- <img :src="item.photo" /> -->
                                </div>
                                <div
                                    class="col-lg-10 col-md-6 col-sm-12 col-6 d-flex flex-column justify-content-evenly info"
                                >
                                    <div
                                        class="d-flex justify-content-center title p-1"
                                    >
                                        <a herf="#" :title="item.name">
                                            {{ item.name }}
                                        </a>
                                    </div>

                                    <div class="d-flex description">
                                        <div>
                                            {{ item.description }}
                                        </div>
                                    </div>
                                    <div class="d-flex author">
                                        作者:
                                        <span v-for="name in item.author">{{
                                            name
                                        }}</span>
                                    </div>
                                    <div
                                        class="d-flex justify-content-end stock"
                                    >
                                        <span>
                                            庫存:
                                            <span class="keyword">{{
                                                item.stock
                                            }}</span></span
                                        >
                                    </div>
                                    <div
                                        class="d-flex justify-content-end price"
                                    >
                                        <span
                                            :style="
                                                item.discount != 0
                                                    ? 'text-decoration: line-through; text-decoration-color: red;'
                                                    : ''
                                            "
                                            >售價:<span
                                                class="keyword"
                                                :style="{
                                                    color:
                                                        item.discount != 0
                                                            ? '#FF2D2D'
                                                            : '',
                                                }"
                                                >{{
                                                    item.entity
                                                        ? item.entityPrice
                                                        : item.ebookPrice
                                                }}</span
                                            >元</span
                                        >
                                        <span v-show="item.discount != 0">
                                            優惠價:
                                            <span
                                                class="keyword"
                                                style="color: #ff2d2d"
                                            >
                                                {{
                                                    item.entity
                                                        ? (
                                                              (item.entityPrice *
                                                                  item.discount) /
                                                              100
                                                          ).toFixed(0)
                                                        : (
                                                              (item.ebookPrice *
                                                                  item.discount) /
                                                              100
                                                          ).toFixed(0)
                                                }}
                                            </span>
                                            元
                                        </span>
                                    </div>
                                    <div
                                        class="d-flex justify-content-between align-items-end other"
                                    >
                                        <div class="d-flex">
                                            <span
                                                v-for="tag in item.bookTag"
                                                class="book_tag"
                                            >
                                                #{{ tag }}&emsp;
                                            </span>
                                        </div>
                                        <div class="d-flex">
                                            <span
                                                v-for="tag in item.saleTag"
                                                class="sale_tag"
                                            >
                                                #{{ tag }}&emsp;
                                            </span>
                                        </div>

                                        <button class="shoppingCar_btn">
                                            <i class="bi bi-cart2"></i
                                            >&ensp;加入購物車
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div v-if="dataloaded">
                    <pagination
                        v-model="currentPage"
                        :totalPages="totalPages"
                        @page-changed="handlePageChange"
                    ></pagination>
                </div>
                <div v-else>
                    <div class="loading-overlay">
                        <div class="loading-spinner-container">
                            <div class="loading-spinner"></div>
                        </div>
                        <div class="loading-text">資料載入中...</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { searchAlgolia } from '../../plugin/Algolia.js'
import api from '@/axios/axios'
import pagination from '../../components/content/pagination.vue'
export default {
    components: {
        pagination,
    },
    data() {
        return {
            collapseFilterStatus: false,
            collapseBtnType: [],
            bookListInfo: [],
            bookSoldTypeList: ['entity', 'ebook'],
            sortType: ['最多瀏覽', '熱銷中', '最早發行', '最新發行'],
            selectSubTypes: [],
            sort: '最多瀏覽',
            sortValue: 'views',
            isForeign: false,
            dataloaded: false,
            totalPages: 1,
            itemsPerPage: 2,
            currentPage: 1,
            searchInput: '',
            a: 1,
        }
    },
    methods: {
        toggleFilterCollapse() {
            this.collapseFilterStatus = !this.collapseFilterStatus
            let icon = document.getElementById('icon_filter')
            if (this.collapseFilterStatus) {
                icon.style.transform = 'rotate(90deg)'
            } else {
                icon.style.transform = 'rotate(0deg)'
            }
        },
        toggleBtnTypeCollapse(index) {
            this.collapseBtnType[index].show = !this.collapseBtnType[index].show
        },
        getFilterType() {
            let typeArray = Object.entries(
                this.$store.state.generalInfo.typeList,
            ).map(([key, value]) => ({
                id: key,
                ...value,
            }))
            this.collapseBtnType = typeArray.map(type => ({
                ...type,
                show: false,
                checked: new Array(type.subTypes.length).fill(false),
            }))
        },
        handleTypeFilter() {
            if (this.bookSoldTypeList.length != 0) {
                this.dataloaded = false
                this.currentPage = 1
                this.getDataFromAlgolia()
            }
        },
        handleSortChange(item, index) {
            this.currentPage = 1
            this.dataloaded = false
            this.sort = item
            if (index == 0) {
                this.sortValue = 'views'
            } else if (index == 1) {
                this.sortValue = 'sold'
            } else if (index == 2) {
                this.sortValue = 'createTime_asc'
            } else if (index == 3) {
                this.sortValue = 'createTime'
            }
            this.getDataFromAlgolia(
                this.searchInput,
                this.isForeign,
                this.selectSubTypes,
                this.sortValue,
                this.currentPage,
                this.itemsPerPage,
            )
        },
        async getDataFromAlgolia(isRouteQuery = false) {
            console.log('getDataFromAlgolia')
            if (!isRouteQuery) {
                this.selectSubTypes = this.collapseBtnType.reduce(
                    (acc, item) => {
                        item.subTypes.forEach((subType, index) => {
                            if (item.checked[index]) {
                                acc.push(subType)
                            }
                        })
                        return acc
                    },
                    [],
                )
            }
            try {
                const results = await searchAlgolia(
                    this.searchInput,
                    this.isForeign,
                    this.selectSubTypes,
                    this.sortValue,
                    this.currentPage,
                    this.itemsPerPage,
                    this.bookSoldTypeList,
                )
                if (results) {
                    this.bookListInfo = results[0]?.hits || []
                    const totalHits = results[0]?.nbHits || 0
                    this.totalPages = Math.ceil(totalHits / this.itemsPerPage)
                } else {
                    console.error('未返回搜索结果')
                }
            } catch (error) {
                console.error('從 Algolia 獲取數字發生錯誤:', error.message)
            } finally {
                this.dataloaded = true
            }
        },
        handlePageChange(newPage, isIncreasing) {
            this.dataloaded = false
            this.currentPage = newPage
            this.getDataFromAlgolia()
        },
        initRouteData() {
            if (this.$route.query.rowData.query != undefined) {
                const rowData = this.$route.query.rowData
                this.searchInput = rowData.query
                this.isForeign = rowData.isForeign
                this.selectSubTypes = rowData.subTypes
                this.sortValue = rowData.sortValue
                if (this.sortValue == 'views') {
                    this.sort = this.sortType[0]
                } else if (this.sortValue == 'sold') {
                    this.sort = this.sortType[1]
                } else if (this.sortValue == 'createTime_asc') {
                    this.sort = this.sortType[2]
                } else if (this.sortValue == 'createTime') {
                    this.sort = this.sortType[3]
                }
                if (!(rowData.ebook && rowData.entity)) {
                    this.bookSoldTypeList = []
                    if (rowData.entity) {
                        this.bookSoldTypeList.push('entity')
                    }
                    if (rowData.ebook) {
                        this.bookSoldTypeList.push('ebook')
                    }
                }
            } else {
            }
        },
        initFilterShowBySubTypes() {
            this.collapseBtnType.forEach((type, index1) => {
                let temp = false
                // 檢查該類型下的子類型
                type.subTypes.forEach((subType, index2) => {
                    // 如果子類型在 selectSubTypes 陣列中，則設為 true
                    if (this.selectSubTypes.includes(subType)) {
                        temp = true
                        type.checked[index2] = true
                    } else {
                        type.checked[index2] = false
                    }
                })
                // 若至少有一個子類型被選中，則 show 設為 true
                if (temp) {
                    const triggerElement = document.querySelector(
                        '#collapseBtn_type_' +
                            index1 +
                            ' [data-bs-toggle="collapse"]',
                    )
                    if (triggerElement) {
                        triggerElement.dispatchEvent(new Event('click'))
                    }
                }
            })
        },
    },
    created() {
        this.getFilterType()
        if (this.$route.query.rowData != undefined) {
            this.initRouteData()
            this.getDataFromAlgolia(true)
        } else {
            this.getDataFromAlgolia()
        }
    },
    beforeMount() {},
    mounted() {
        if (this.selectSubTypes.length != 0) {
            this.initFilterShowBySubTypes()
        }
        this.$parent.observeNavbarHeight()
    },
}
</script>

<style lang="scss" scoped>
@import '../../scss/content/loading.scss';
@import '/src/scss/hamburgerBtn.scss';
@import '/src/scss/content/general.scss';
@import '/src/scss/content/filterArea.scss';
@import '/src/scss/content/booklist.scss';
.menu {
    --s: 1em;
    --c: var(--color-content-filterarea-collapse_btn_type_hover);
}
.searchBtn {
    cursor: pointer;
    transition: transform 0.3s ease;
    &:hover {
        transform: scale(1.2);
    }
}
.soldTypefilter {
    background-color: var(--color-content-background);
    ::v-deep .el-checkbox-group {
        display: flex;
        justify-content: space-evenly;
    }
    ::v-deep .el-checkbox {
        margin: 0px;
    }
    ::v-deep .el-checkbox__label {
        height: 33px;
        font-size: 16px;
        color: var(--color-content-text);
        line-height: 33px;
    }
}
</style>
